import ast, copy, hashlib, json, math, pathlib, random, subprocess
p=json.loads(pathlib.Path('proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','tools.py','resolve','run://r-001']))

def validate(x,s,path='study'):
 t=s.get('type'); types={'object':dict,'array':list,'string':str,'boolean':bool}
 if t in types: assert isinstance(x,types[t]),(path,t)
 if 'enum' in s: assert x in s['enum'],path
 if 'const' in s: assert x==s['const'],path
 if isinstance(x,str): assert len(x)>=s.get('minLength',0),path
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,y in enumerate(x):validate(y,s.get('items',{}),f'{path}[{i}]')
 if isinstance(x,dict):
  assert all(k in x for k in s.get('required',[])),path
  if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{})),path
  for k,y in x.items():
   if k in s.get('properties',{}):validate(y,s['properties'][k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
base=ast.parse(pathlib.Path('history_r0005_query_blind.py').read_text())
base_model=next(n for n in base.body if isinstance(n,ast.ClassDef) and n.name=='Model')
base_methods={n.name:n for n in base_model.body if isinstance(n,ast.FunctionDef)}
allow={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
normalized=[]
for v in p['variants']:
 file=v['file']; assert pathlib.Path(file).name==file and file.endswith('.py')
 data=pathlib.Path(file).read_text(); tree=ast.parse(data,filename=file); compile(data,file,'exec')
 config=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(y,ast.Name) and y.id=='CONFIG' for y in n.targets))
 assert ast.literal_eval(config.value)==v['config']
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):assert all(y.name.split('.')[0] in allow for y in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in allow
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','eval','exec','__import__'}
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:n for n in model.body if isinstance(n,ast.FunctionDef)}
 for name in ('forward','_statistics','_evidence_from_statistics','_pair_statistics','_pair_evidence','_masked_weights','_score','_context_queries'):
  assert ast.dump(methods[name])==ast.dump(base_methods[name]),(file,name)
 # All parameter constructors and their order stay literally unchanged.
 def constructors(node):
  return [ast.dump(n.value) for n in node.body if isinstance(n,ast.Assign) and any(isinstance(k,ast.Call) and isinstance(k.func,ast.Attribute) and isinstance(k.func.value,ast.Name) and k.func.value.id=='nn' for k in ast.walk(n.value))]
 assert constructors(methods['__init__'])==constructors(base_methods['__init__']),file
 for key,val in v['config'].items():
  if key not in ('fusion_binding','fusion_scale'): assert val==ast.literal_eval(next(n for n in base.body if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name) and n.targets[0].id=='CONFIG').value)[key]
 # Confirm that exactly the declared score fusion and extra return metadata
 # differ in _field_views. Check inheritance by normalizing these changes.
 fields=copy.deepcopy(methods['_field_views'])
 fields.body=[n for n in fields.body if not(isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name) and n.targets[0].id=='shared_score')]
 for n in fields.body:
  if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name) and n.targets[0].id=='shared_weights':
   old=next(y for y in base_methods['_field_views'].body if isinstance(y,ast.Assign) and isinstance(y.targets[0],ast.Name) and y.targets[0].id=='shared_weights'); n.value=copy.deepcopy(old.value)
  if isinstance(n,ast.Return):
   retained=[(k,val) for k,val in zip(n.value.keys,n.value.values) if not(isinstance(k,ast.Constant) and k.value in ('shared_score','history_value'))]
   n.value.keys=[k for k,val in retained];n.value.values=[val for k,val in retained]
 assert ast.dump(fields)==ast.dump(base_methods['_field_views']),file
 config.value=ast.Constant(value='CONFIG_ONLY_DIFFERENCE')
 normalized.append(ast.dump(tree))
 print(file,'syntax/source/API/constructor checks passed; SHA256',hashlib.sha256(data.encode()).hexdigest())
assert len(set(normalized))==1
assert {a['knowledge_id'] for a in p['knowledge_assessments']}=={'taac2026-industry-1-queryformer','taac2026-academic-2-unidac','taac2026-academic-3-unitokenformer'}
assert all(a['decision'] in ('used','considered','rejected','unresolved') for a in p['knowledge_assessments'])
print('Proposal schema, evidence IDs, protocol, factorial and source identity checks passed.')

# Independent scalar formula checks; these do NOT run Torch/model code.
def fusion(cs,bs,ac,ab,binding,scale):
 if ac and ab:return [.5*(c+b) for c,b in zip(cs,bs)]
 gc,gb=(ac,ab) if binding=='available' else (ab,ac)
 den=max(int(ac)+int(ab),1) if scale=='active' else 2
 return [((c if gc else 0)+(b if gb else 0))/den for c,b in zip(cs,bs)]
def softmax(s,mask):
 if not any(mask):return [0.0]*len(s)
 top=max(x for x,m in zip(s,mask) if m)
 ex=[math.exp(x-top) if m else 0.0 for x,m in zip(s,mask)]
 total=sum(ex); return [x/total for x in ex]
random.seed(73)
for _ in range(500):
 cs=[random.uniform(-30,30) for i in range(8)];bs=[random.uniform(-30,30) for i in range(8)]
 mask=[random.choice((True,False)) for i in range(8)]
 for ac in (False,True):
  for ab in (False,True):
   for binding in ('available','crossed'):
    for scale in ('active','fixed'):
     scores=fusion(cs,bs,ac,ab,binding,scale); w=softmax(scores,mask)
     assert all(math.isfinite(x) for x in scores+w)
     assert abs(sum(w)-int(any(mask)))<1e-12
     assert all(weight==0 for weight,m in zip(w,mask) if not m)
     if ac and ab:assert scores==[.5*(x+y) for x,y in zip(cs,bs)]
     if not ac and not ab:
      assert scores==[0]*8
      assert all(abs(weight-(1/sum(mask) if m else 0))<1e-12 for weight,m in zip(w,mask))
     if ac "'^ ab:
      known=cs if ac else bs; missing=bs if ac else cs
      expected=known if binding=='"'available' else missing
      assert scores==[x*(1 if scale=='active' else .5) for x in expected]
 # Correct binding ignores arbitrary absent-scorer perturbations; crossed does not.
 assert fusion(cs,bs,True,False,'available','active')==fusion(cs,[x+19 for x in bs],True,False,'available','active')
 assert fusion(cs,bs,True,False,'available','active')==fusion(bs,cs,False,True,'available','active')
assert softmax([1e9,-1e9,0],[True,True,False])==[1.0,0.0,0.0]
assert softmax([1e9,-1e9],[False,False])==[0.0,0.0]
# Shared value pooling remains nonzero for unknown targets and nonempty history;
# absent target identity suppresses scores, not all history evidence.
w=softmax(fusion([2.,-1.],[3.,1.],False,False,'available','active'),[True,True])
assert sum(a*b for a,b in zip(w,[2.,4.]))==3.0
print('Independent scalar checks passed: all availability/scale cells, all-known invariance, both-missing uniform fallback, absent-score invariance, field swap, padding, empty history and finite extreme softmax.')
print('Torch execution, gradients, host metrics and measured cost remain unverified; no packages installed or training invoked.')
PY"

